```python
import time
from typing import Callable, Dict, Any
import sys

class LRUCacheWithMetrics(LRUCache):
    """성능 메트릭을 추적하는 LRU 캐시"""

    def __init__(self, capacity: int):
        super().__init__(capacity)
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.access_times = {}  # key -> [access_times]

    def get(self, key: Any):
        result = super().get(key)
        if result is not None:
            self.hits += 1
            if key not in self.access_times:
                self.access_times[key] = []
            self.access_times[key].append(time.time())
        else:
            self.misses += 1
        return result

    def put(self, key: Any, value: Any):
        old_size = len(self.cache)
        super().put(key, value)
        if len(self.cache) < old_size:
            self.evictions += 1

    def hit_ratio(self) -> float:
        total = self.hits + self.misses
        return self.hits / total if total > 0 else 0

    def stats(self) -> str:
        return f"""
        Hits: {self.hits} | Misses: {self.misses} | Hit Ratio: {self.hit_ratio():.2%}
        Evictions: {self.evictions} | Current Size: {len(self.cache)}/{self.capacity}
        Memory Usage: {sys.getsizeof(self.cache)} bytes
        """
