class OptimizedCSVParser(CSVParser):
    """성능과 안정성을 강화한 CSV 파서"""

    def __init__(self, *args, chunk_size: int = 8192, **kwargs):
        super().__init__(*args, **kwargs)
        self.chunk_size = chunk_size
        self._field_cache = {}

    def parse_stream_optimized(self, file_obj, skip_empty_rows: bool = True) -> Iterator[List[str]]:
        """최적화된 스트림 파싱 - 청크 단위로 처리"""
        buffer = ""
        row_count = 0

        while True:
            chunk = file_obj.read(self.chunk_size)
            if not chunk:
                break

            buffer += chunk
            lines = buffer.split('\n')
            buffer = lines[-1]

            for line in lines[:-1]:
                if not skip_empty_rows or line.strip():
                    try:
                        row = self.parse_line_internal(line)
                        if row:
                            row_count += 1
                            yield row
                    except ValueError as e:
                        raise ValueError(f"Error at row {row_count}: {e}")

        if buffer.strip():
            yield self.parse_line_internal(buffer)

    def parse_with_types(self, line: str, type_hints: Dict[int, type]) -> List[Any]:
        """타입 변환과 함께 파싱"""
        fields = self.parse_line_internal(line)

        converted = []
        for i, field in enumerate(fields):
            if i in type_hints:
                try:
                    converted.append(type_hints[i](field) if field else None)
                except (ValueError, TypeError) as e:
                    raise ValueError(f"Type conversion failed for field {i}: {field}")
            else:
                converted.append(field)

        return converted
