## 1. 동시성 문제 (Concurrency Issues)

현재 구현은 **스레드 안전성이 없습니다**. 멀티스레드 환경에서 문제가 발생할 수 있습니다:

```python
import threading
from threading import Lock
from decimal import Decimal

class ThreadSafeVendingMachine(VendingMachine):
    """Thread-safe version of vending machine"""

    def __init__(self, machine_id: str):
        super().__init__(machine_id)
        self._state_lock = Lock()
        self._inventory_lock = Lock()
        self._transaction_lock = Lock()

    def _transition_to(self, new_state: VendingMachineState) -> None:
        """Thread-safe state transition"""
        with self._state_lock:
            super()._transition_to(new_state)

    def add_payment(self, amount: Decimal) -> bool:
        """Thread-safe payment addition"""
        with self._state_lock:
            return super().add_payment(amount)

    def select_item(self, item_id: str) -> bool:
        """Thread-safe item selection with inventory lock"""
        with self._state_lock, self._inventory_lock:
            return super().select_item(item_id)

    def _process_transaction(self) -> bool:
        """Thread-safe transaction processing"""
        with self._state_lock, self._inventory_lock, self._transaction_lock:
            return super()._process_transaction()

# 문제점: Lock ordering이 교착상태(deadlock)를 초래할 수 있음
# 해결책: 항상 동일한 순서로 락을 획득
